Widget originalInfoCard(String title, String detail) => Padding(
  padding: const EdgeInsets.all(20),
  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
    Text(title, style: const TextStyle(fontSize: 24, fontWeight: FontWeight.w600)),
    const SizedBox(height: 12), Text(detail),
  ]),
);

function OriginalInfoCard({ title, detail, headingId }) {
  return <article aria-labelledby={headingId} className="original-info-card">
    <h2 id={headingId}>{title}</h2><p>{detail}</p>
  </article>;
}
